(()=>{const traces=window.MindscapeTraces;const panel=document.getElementById('diagnostic-panel');if(!Array.isArray(traces)||traces.length!==2||traces.some(t=>!t.events.length||t.sourceSha256.length!==64)){panel.textContent='Recorded evidence could not be loaded. Read the linked source documents.';return}const tabs=[...document.querySelectorAll('[data-trace]')],slider=document.getElementById('trace-event'),previous=document.getElementById('trace-previous'),next=document.getElementById('trace-next');let traceIndex=0;function render(){const trace=traces[traceIndex],index=Number(slider.value),event=trace.events[index];slider.max=trace.events.length-1;document.getElementById('diagnostic-summary').textContent=`${trace.calls} actual model calls · ${trace.backend} ${trace.precision} · ${trace.eventCount} total observed events. This selection contains ${trace.events.length} recorded events.`;document.getElementById('trace-position').textContent=`Event ${index+1}/${trace.events.length} selected · t+${event.elapsed_seconds.toFixed(3)} s from observer start`;document.getElementById('event-title').textContent=event.kind.replaceAll('_',' ');document.getElementById('event-values').textContent=JSON.stringify(event.observed,null,2);document.getElementById('trace-outcome').textContent=`Final independently verified outcome: ${trace.success?'passed':'unsuccessful'}.`;document.getElementById('trace-result').textContent=JSON.stringify({task:trace.taskId,model:trace.model,output:trace.output,failures:trace.failures,sourceSHA256:trace.sourceSha256},null,2);previous.disabled=index===0;next.disabled=index===trace.events.length-1}function select(i){traceIndex=i;slider.value=0;tabs.forEach((t,j)=>{t.setAttribute('aria-selected',String(i===j));t.tabIndex=i===j?0:-1});panel.setAttribute('aria-labelledby',tabs[i].id);render()}tabs.forEach((t,i)=>{t.addEventListener('click',()=>select(i));t.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?1:1-i;select(j);tabs[j].focus()}})});slider.addEventListener('input',render);previous.addEventListener('click',()=>{slider.value=Number(slider.value)-1;render()});next.addEventListener('click',()=>{slider.value=Number(slider.value)+1;render()});render();const links=[...document.querySelectorAll('.architecture-toc a')];const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)links.forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})},{rootMargin:'-15% 0px -65% 0px',threshold:0});document.querySelectorAll('.architecture-article>section[id]').forEach(s=>observer.observe(s));})();
